insert into public.settings (id, company_name, short_name, tagline, about, phone, phone2, email, address, zalo, facebook, map_embed_url, business_hours) values (1, 'Công ty TNHH TM DV Thiết bị Nhà máy Thành Danh', 'Thành Danh', 'Chuyên cung cấp vật tư nhà máy', 'Thành Danh chuyên cung cấp vật tư, thiết bị và phụ tùng cho nhà máy: thiết bị điện công nghiệp và tự động hóa, thiết bị khí nén – thủy lực, motor – hộp giảm tốc, phụ kiện đường ống và van các loại. Chúng tôi phân phối sản phẩm từ các thương hiệu hàng đầu như Siemens, Schneider Electric, Mitsubishi Electric, Omron, Festo, SMC, ABB… với báo giá nhanh và giao hàng tận nơi.', '0907 646 647', '0939 113 115', null, '53/22 Đường số 4, Phường Bình Tân, Thành phố Hồ Chí Minh, Việt Nam', '0907646647', null, 'https://www.google.com/maps?q=53%2F22%20%C4%90%C6%B0%E1%BB%9Dng%20s%E1%BB%91%204%2C%20B%C3%ACnh%20T%C3%A2n%2C%20H%E1%BB%93%20Ch%C3%AD%20Minh&output=embed', 'Thứ 2 – Thứ 7: 7:30 – 17:30')
insert into public.categories (slug, name, description, icon, sort_order) values
