  ('tu-dong-hoa', 'Tự động hóa', 'PLC, HMI, biến tần, servo, cảm biến và bộ điều khiển cho dây chuyền sản xuất.', 'cpu', 2),
  ('khi-nen-thuy-luc', 'Khí nén – Thủy lực', 'Xi lanh, van điện từ, bộ lọc khí, đầu nối, ống hơi và thiết bị thủy lực.', 'wind', 3),
  ('motor-hop-giam-toc', 'Motor – Hộp giảm tốc', 'Động cơ điện, motor giảm tốc, hộp số và phụ kiện truyền động.', 'cog', 4),
