insert into public.products (slug, name, category_id, brand_id, summary, description, featured, published) values
  ('plc-siemens-s7-1200', 'Bộ lập trình PLC Siemens S7-1200', (select id from public.categories where slug = 'tu-dong-hoa'), (select id from public.brands where slug = 'siemens'), 'PLC nhỏ gọn cho các ứng dụng điều khiển máy và dây chuyền vừa và nhỏ.', 'Dòng PLC S7-1200 tích hợp cổng PROFINET, lập trình bằng TIA Portal. Liên hệ để được tư vấn chọn CPU, module mở rộng và báo giá.', true, true),
  ('bien-tan-mitsubishi-fr-e800', 'Biến tần Mitsubishi FR-E800', (select id from public.categories where slug = 'tu-dong-hoa'), (select id from public.brands where slug = 'mitsubishi-electric'), 'Biến tần đa năng cho bơm, quạt, băng tải.', 'Biến tần FR-E800 hỗ trợ nhiều chuẩn truyền thông công nghiệp. Liên hệ để được tư vấn công suất phù hợp.', true, true),
  ('cam-bien-tiem-can-omron', 'Cảm biến tiệm cận Omron', (select id from public.categories where slug = 'tu-dong-hoa'), (select id from public.brands where slug = 'omron'), 'Cảm biến tiệm cận điện cảm, nhiều kích thước M8 – M30.', 'Phát hiện vật thể kim loại không tiếp xúc, dùng trong máy đóng gói, băng tải, máy CNC.', true, true),
  ('aptomat-schneider-easy9', 'Aptomat (MCB) Schneider Easy9', (select id from public.categories where slug = 'thiet-bi-dien-cong-nghiep'), (select id from public.brands where slug = 'schneider-electric'), 'Cầu dao tự động bảo vệ quá tải và ngắn mạch.', 'Đầy đủ dòng định mức và số cực. Liên hệ để nhận báo giá theo số lượng.', true, true),
  ('contactor-abb-af', 'Contactor ABB dòng AF', (select id from public.categories where slug = 'thiet-bi-dien-cong-nghiep'), (select id from public.brands where slug = 'abb'), 'Khởi động từ cho động cơ và tải công nghiệp.', 'Cuộn coil dải điện áp rộng, độ bền cao. Liên hệ để được tư vấn chọn mã.', false, true),
  ('xi-lanh-khi-nen-festo', 'Xi lanh khí nén Festo', (select id from public.categories where slug = 'khi-nen-thuy-luc'), (select id from public.brands where slug = 'festo'), 'Xi lanh tiêu chuẩn ISO, nhiều đường kính và hành trình.', 'Phù hợp cho các ứng dụng gá kẹp, đẩy, nâng hạ trong dây chuyền tự động.', true, true),
  ('van-dien-tu-smc', 'Van điện từ khí nén SMC', (select id from public.categories where slug = 'khi-nen-thuy-luc'), (select id from public.brands where slug = 'smc'), 'Van điện từ 5/2, 5/3 điều khiển xi lanh khí nén.', 'Đa dạng điện áp coil và kiểu kết nối. Liên hệ để được báo giá nhanh.', true, true),
  ('cam-bien-quang-sick', 'Cảm biến quang SICK', (select id from public.categories where slug = 'tu-dong-hoa'), (select id from public.brands where slug = 'sick'), 'Cảm biến quang thu phát, phản xạ gương và phản xạ khuếch tán.', 'Độ chính xác cao, phù hợp cho môi trường công nghiệp khắc nghiệt.', false, true),
  ('motor-giam-toc', 'Motor giảm tốc công nghiệp', (select id from public.categories where slug = 'motor-hop-giam-toc'), null, 'Motor giảm tốc cốt thẳng, cốt vuông góc nhiều tỉ số truyền.', 'Tư vấn chọn công suất, tỉ số truyền và kiểu lắp đặt theo yêu cầu thực tế.', true, true),
  ('van-bi-inox', 'Van bi inox', (select id from public.categories where slug = 'phu-kien-duong-ong-van'), null, 'Van bi inox nối ren, mặt bích các cỡ.', 'Dùng cho hệ thống nước, khí, hóa chất nhẹ. Cung cấp kèm co, tê, rắc co đồng bộ.', false, true)
